def get_capability_definition(profile_manager, capability_definition_name):
    """
    Returns the capability definition with the given name.

    profile_manager
        Reference to the profile manager.

    capability_definition_name
        Name of the capability definition.
    """
    for profile in profile_manager.profiles:
        for capability_definition in profile.capability_definitions:
            if capability_definition.name == capability_definition_name:
                return capability_definition
    return None


